// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _test(address target, bytes memory data, uint256 amount) internal {
        vm.assume(address(this).balance >= amount);
        bool didRevert;
        try c.Command{value: amount}(target, data) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        assertTrue(!(c.Owner() == address(this)) || didRevert == false);
    }

    function testFuzz_test(address target, bytes memory data, uint256 amount) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(target, data, amount);
    }

    receive() external payable {}
}
